void rules(const CombatContent& c,const SaveSnapshot& saved,const std::filesystem::path& root){
 GameSession resumed(c.items,saved.session,c.facts);finishSaveContinuation(resumed,saved);auto base=resumed.exportState();auto e=c.entries.at("post-pickup");e.map=196;e.playerTile={9,6};e.direction=Direction::Up;e.positions.clear();e.directions.clear();e.pages.clear();e.through.clear();e.session=base;
 bool allow=false;int failures=0;GameSession state(c.items,base,c.facts);CombatScene scene(c,state,e,safe,[&](const SceneDefinition& definition){if(definition.width==34&&!allow){++failures;throw std::runtime_error("injected terminal tail destination");}});
 scene.update(key());for(int n=0;n<30000&&failures<2;++n){scene.update(n%8==0?key():InputFrame{});scene.takePresentation();}
 need(failures>=2&&scene.mapId()==196&&!state.flag(528)&&state.variable(628)==2&&!state.flag(1)&&!state.flag(18),"Terminal failed destination prematurely committed528/control");
 need(state.exportState().inventory==base.inventory,"Terminal failed preparation invented inventory");allow=true;for(int n=0;n<3000&&scene.foreground()!=ForegroundKind::None;++n){scene.update(n%8==0?key():InputFrame{});scene.takePresentation();}need(scene.mapId()==195&&state.flag(528)&&state.flag(1)&&state.flag(18),"Terminal retry omitted late129 and tail");
 scene.deactivate();const auto retired=state.exportState();for(int n=0;n<90;++n){scene.update(key());}need(state.exportState()==retired,"Retired terminal scene continued writes");
 // Source save rejection is tested before adaptation and preserves the active session.
 GameApplication live(c,"title",safe);std::string error;need(live.restore(saved,error),"Rules actual source restore failed");const auto before=live.session().exportState();const auto generation=live.generation();auto malformed=saved;malformed.session.worldValues[c.facts.variables.at(628)]=2;need(!live.restore(malformed,error)&&live.generation()==generation&&live.session().exportState()==before,"Malformed partial terminal Load replaced current game");
 for(int mode=0;mode<4;++mode){auto bad=saved;if(mode==0){bad.session.worldValues[c.facts.variables.at(629)]=3;}if(mode==1){bad.session.worldValues[c.facts.variables.at(635)]=-1;}if(mode==2){bad.session.worldFlags[c.facts.switches.at(530)]=true;}if(mode==3){bad.session.worldFlags[c.facts.switches.at(556)]=true;}bool rejected=false;try{validateSave(c,bad);}catch(const std::exception&){rejected=true;}need(rejected,"Invalid evacuation save domain accepted");}
 auto stable=saved;stable.session.worldFlags[c.facts.switches.at(528)]=true;stable.session.worldValues[c.facts.variables.at(628)]=2;validateSave(c,stable);need(decodeSave(c,encodeSave(c,stable))==stable,"Valid terminal-only save roundtrip failed");
 SaveFiles files(c,root/"transaction");need(files.write(1,saved).outcome==WriteOutcome::Committed,"Original isolated disk failed");const auto old=read(root/"transaction/slot-01.json");SaveFiles failing(c,root/"transaction",[](std::string_view phase){if(phase=="replace"){throw std::runtime_error("injected terminal ordinary replace");}});need(failing.write(1,stable).outcome==WriteOutcome::RecoveryRequired&&read(root/"transaction/slot-01.json")==old,"Failed terminal save replaced original isolated disk");
 std::ofstream(root/"rules-result.json")<<Json{{"terminal_late528_failure_retry",true},{"retired_scene_no_writes",true},{"invalid_stage_rejected",4},{"valid_terminal_only_roundtrip",true},{"save_replace_failure_preserved",true},{"failedLoad_preserved",true}}.dump(2)<<'\n';std::cout<<"G6-02 late terminal/retired scene/domain/save failure PASS\n";
}

